<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Panel — ANN Studio</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=Italiana&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/admin.css"></head>
<body>
<link rel="stylesheet" href="assets/admin-extra.css">
<section class="auth" id="auth"><div class="auth-card"><a href="index.php" class="logo">ANN <small>STUDIO</small></a><p class="eyebrow">Panel administrativo</p><h1 id="authTitle">Acceso privado</h1><p id="authCopy">Ingresa tu contraseña para gestionar la tienda.</p><form id="authForm"><input type="password" id="password" minlength="10" placeholder="Contraseña" required><button>Continuar</button></form><p class="error" id="authError"></p></div></section>
<div class="app" id="app"><aside><a class="logo" href="index.php">ANN <small>STUDIO</small></a><nav><button class="active" data-view="overview">Resumen</button><button data-view="products">Productos</button><button data-view="orders">Pedidos</button></nav><button class="logout" id="logout">Cerrar sesión</button></aside><main><header><div><p class="eyebrow">Administración</p><h1 id="pageTitle">Resumen de la tienda</h1></div><a href="index.php" target="_blank">Ver tienda ↗</a></header>
<section id="overview" class="view active"><div class="metrics" id="metrics"></div><div class="dashboard-grid"><article class="panel"><div class="panel-head"><h2>Productos más consultados</h2><span>Interés → intención</span></div><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Vistas</th><th>En bolsa</th><th>Pedidos</th></tr></thead><tbody id="ranking"></tbody></table></div></article><article class="panel"><div class="panel-head"><h2>Interés por categoría</h2></div><div id="categories" class="bars"></div></article></div></section>
<section id="products" class="view"><div class="section-actions"><div><h2>Catálogo</h2><p>Edita imágenes, códigos, variantes y precios.</p></div><button id="newProduct">+ Nuevo producto</button></div><div class="product-list" id="productList"></div></section>
<section id="orders" class="view"><div class="section-actions"><div><h2>Pedidos iniciados</h2><p>Solicitudes enviadas al flujo de WhatsApp. Se actualiza automáticamente.</p></div><button id="refreshOrders">Actualizar ahora</button></div><div id="orderList" class="order-list"></div></section>
</main></div>
<dialog id="productModal"><button class="modal-close">×</button><h2>Producto</h2><form id="productForm" enctype="multipart/form-data"><input type="hidden" name="id"><input type="hidden" name="image_current"><label class="image-upload"><span>Fotografía del producto</span><div class="image-preview" id="imagePreview"><span>Seleccionar imagen</span></div><input type="file" name="image" id="imageInput" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG o WebP · máximo 6 MB</small></label><div class="form-grid"><label>Nombre<input name="name" required></label><label>Código<input name="code" required></label><label>Categoría<select name="category"><option>Ropa</option><option>Lociones</option><option>Carteras</option><option>Gafas</option><option>Accesorios</option></select></label><label>Precio (L)<input type="number" name="price" min="0" step=".01" required></label><label>Colores / variantes<input name="colors" placeholder="Negro, Vino"></label><label>Tallas<input name="sizes" placeholder="S, M, L"></label><label>Color visual<input name="tone" type="color"></label><label>Forma<select name="shape"><option value="dress">Vestido</option><option value="top">Blusa</option><option value="set">Conjunto</option><option value="bottle">Loción</option><option value="bag">Cartera</option><option value="glasses">Gafas</option><option value="earrings">Aretes</option><option value="necklace">Collar</option></select></label></div><label>Descripción<textarea name="description" rows="3"></textarea></label><button class="primary">Guardar producto</button></form></dialog>
<script src="assets/admin.js?v=2"></script></body></html>
